reply:
I've composed a metrics overview with a 2×2 grid of KPI tiles and a current-versus-previous comparison chart. The tiles use `metric_row`, which provides value, label, and up/down trend for each metric.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "metrics-overview",
      "catalogId": "https://a2uicatalog.ai/catalog/c-data-display.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "metrics-overview",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "1.5rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "id": "overview-heading",
                  "component": "heading",
                  "text": "Metrics overview"
                },
                {
                  "id": "kpi-tiles",
                  "component": "metric_row",
                  "cols": 2,
                  "metrics": [
                    {
                      "value": "482K",
                      "prefix": "$",
                      "label": "Revenue",
                      "sub": "vs. last month",
                      "accent": "#22c55e",
                      "trend": "up"
                    },
                    {
                      "value": "12,840",
                      "label": "Active users",
                      "sub": "vs. last month",
                      "accent": "#22c55e",
                      "trend": "up"
                    },
                    {
                      "value": "2.3",
                      "suffix": "%",
                      "label": "Churn rate",
                      "sub": "vs. last month",
                      "accent": "#ef4444",
                      "trend": "down"
                    },
                    {
                      "value": "184",
                      "suffix": " ms",
                      "label": "Avg. response time",
                      "sub": "vs. last month",
                      "accent": "#ef4444",
                      "trend": "down"
                    }
                  ]
                }
              ]
            },
            {
              "blocks": [
                {
                  "id": "comparison-chart",
                  "component": "chartjs_bar",
                  "labels": ["Jan", "Feb", "Mar", "Apr", "May", "Jun"],
                  "datasets": [
                    {
                      "label": "Current period",
                      "data": [320, 345, 410, 388, 436, 482]
                    },
                    {
                      "label": "Previous period",
                      "data": [290, 310, 335, 360, 372, 395]
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
